INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 1, 'theory', 'Квиз: требования и прикидки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 0, 'Какое требование относится к нефункциональным?', '["Пользователь может создать заметку","Сервис отвечает за 200 мс в 99% случаев","Заметки можно искать по тексту","Пользователь может удалить заметку"]', 1, 'Нефункциональные требования описывают качество: задержку, доступность, объём, стоимость. Остальное — функции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 1, 'Сервис получает 10 млн активных пользователей в день по 20 действий. Сколько это примерно запросов в секунду в среднем?', '["Около 20","Около 2 300","Около 200 000","Около 20 млн"]', 1, '200 млн запросов в день делим на ~86 тысяч секунд — около 2–3 тысяч в секунду; на пик закладывают в 2–3 раза больше.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 2, 'Почему задержку оценивают по p99, а не по среднему?', '["p99 всегда меньше среднего","Среднее скрывает редкие медленные запросы, а их видят пользователи","p99 проще считать","Среднее нельзя посчитать"]', 1, 'Хвост распределения определяет ощущения пользователей: на странице из множества запросов медленный попадается почти всегда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 3, 'Что произойдёт с доступностью цепочки из трёх компонентов по 99,9% каждый?', '["Станет 99,9%","Станет выше 99,99%","Станет около 99,7%","Станет 100%"]', 2, 'Доступности перемножаются: 0,999³ ≈ 0,997. Поэтому добавляют избыточность.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 4, 'Как найти узкое место схемы?', '["Выбрать самый дорогой компонент","Посчитать загрузку каждого компонента и усилить самый загруженный","Добавить серверов приложения","Увеличить число балансировщиков"]', 1, 'Пропускная способность схемы определяется самым загруженным звеном; после усиления его считают заново — узкое место переезжает.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 2, 'theory', 'Квиз: масштабирование и балансировка');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 0, 'Какое ограничение вертикального масштабирования самое существенное?', '["Нужно переписывать программу","Есть предел мощности одной машины, и она остаётся единственной точкой отказа","Нельзя использовать базу данных","Нужен балансировщик"]', 1, 'Вертикальное масштабирование упирается в потолок и не даёт резервирования; зато программу менять не нужно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 1, 'Что значит «приложение без состояния»?', '["Приложение не пишет логи","Любой экземпляр может обработать любой запрос: сессии и данные лежат во внешних хранилищах","Приложение не использует память","Приложение работает без базы"]', 1, 'Без состояния — значит, между запросами сервер ничего не помнит у себя, и экземпляры взаимозаменяемы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 2, 'Какой способ хранения сессий избавляет сервер от привязки пользователя к машине и не требует хранилища?', '["Липкие сессии","Сессия в памяти сервера","Подписанный токен у клиента","Куки с паролем"]', 2, 'Подписанный токен проверяется подписью; недостаток — трудно отозвать, поэтому срок жизни короткий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 3, 'Что умеет балансировщик уровня L7 и не умеет L4?', '["Пересылать байты","Маршрутизировать по пути и заголовкам HTTP","Проверять доступность серверов","Распределять запросы по кругу"]', 1, 'L7 понимает прикладной протокол; L4 видит только адреса и порты, зато быстрее и дешевле.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 4, 'Сервису нужно 1000 запросов в секунду, один сервер вытягивает 450. Сколько серверов нужно с запасом N+1 при загрузке не выше 100%?', '["2","3","4","5"]', 2, 'Для 1000 нужно три сервера (1350); с одним запасным — четыре: после потери любого оставшиеся три вытягивают пик.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 3, 'theory', 'Квиз: кэширование и CDN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 0, 'Как работает схема cache-aside при промахе?', '["Приложение возвращает ошибку","Читает из базы, кладёт результат в кэш и отвечает","Ждёт, пока кэш сам загрузит данные","Читает из соседнего сервера"]', 1, 'При промахе приложение читает базу и заполняет кэш, поэтому следующие запросы получат попадание.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 1, 'Что помогает против шторма промахов (cache stampede)?', '["Уменьшить размер кэша","Единый полёт и случайная добавка к TTL","Отключить кэш","Увеличить число баз"]', 1, 'Пока один запрос пересчитывает значение, остальные ждут; разброс TTL не даёт ключам истекать одновременно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 2, 'Как решить проблему устаревших файлов в CDN без дорогого сброса кэша?', '["Ставить TTL в одну секунду","Добавлять версию или хеш в имя файла","Отключать CDN","Ждать, пока файлы устареют сами"]', 1, 'Новая версия получает новое имя; старое просто перестаёт запрашиваться.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 3, 'Для каких данных подходит write-back кэш?', '["Платежи","Счётчики просмотров, где потеря нескольких секунд допустима","Остатки на счёте","Пароли"]', 1, 'Отложенная запись быстрее и снимает нагрузку с базы, но при отказе кэша данные могут пропасть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 4, 'Что произойдёт, если схема держится на кэше с долей попаданий 90%, и кэш внезапно исчезнет?', '["Ничего","Нагрузка на базу вырастет в десять раз","Нагрузка на базу вырастет на 10%","Сервер приложения перестанет работать"]', 1, 'База получала лишь 10% чтений, теперь — все 100%: рост в десять раз; поэтому кэш резервируют и прогревают.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 4, 'theory', 'Квиз: репликация баз данных');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 0, 'Что масштабируют реплики в схеме «лидер и последователи»?', '["Только записи","Чтения","Записи и чтения поровну","Размер диска"]', 1, 'Все записи идут к лидеру; реплики берут на себя чтения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 1, 'Чем рискует асинхронная репликация при отказе лидера?', '["Потерей части подтверждённых записей, не доехавших до реплик","Остановкой чтений навсегда","Дублированием всех данных","Ничем"]', 0, 'Лидер подтвердил запись, но не успел отправить её реплике: после переключения запись потеряна (RPO > 0).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 2, 'Как гарантировать, что пользователь увидит собственную запись при асинхронных репликах?', '["Читать всегда с самой дальней реплики","После записи читать с лидера или с реплики, применившей нужную позицию журнала","Увеличить TTL кэша","Отключить репликацию"]', 1, 'Это гарантия «чтения своих записей»: короткое время читаем с лидера либо проверяем позицию журнала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 3, 'Почему реплика не заменяет резервную копию?', '["Реплика слишком медленная","Ошибочное удаление моментально применится и на репликах","Реплику нельзя хранить в другом регионе","Реплика шифрует данные"]', 1, 'Реплика повторяет все изменения, включая ошибочные; нужны снимки и журнал для восстановления на момент времени.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 4, 4, 'В кворумной репликации N = 3, запись подтверждает W = 2. Сколько R нужно, чтобы чтение гарантированно увидело последнюю запись?', '["R = 1","R = 2","R = 0","R не нужен"]', 1, 'Условие W + R > N: 2 + 2 > 3, множества пересекаются, и хотя бы один опрошенный узел хранит свежую запись.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 5, 'theory', 'Квиз: шардирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 0, 'Чем шард отличается от реплики?', '["Ничем","Шард хранит часть данных, реплика — полную копию","Реплика хранит часть данных, шард — копию","Шард нужен только для чтений"]', 1, 'Шарды делят данные и запись между машинами, а реплики копируют все данные для чтений и надёжности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 1, 'Почему шардирование по автоинкрементному идентификатору с диапазонами плохо?', '["Идентификаторы слишком длинные","Все новые записи попадают в последний диапазон — один шард","Диапазоны нельзя хранить","Хеш лучше диапазона во всех случаях"]', 1, 'Монотонный ключ создаёт горячую точку: последний шард принимает всю запись, остальные простаивают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 2, 'Что даёт консистентное хеширование при добавлении нового узла?', '["Переносится лишь малая доля ключей","Переносятся все данные","Данные не переносятся вовсе","Узлов становится меньше"]', 0, 'На кольце новый узел забирает ключи у соседа; остальные остаются на местах — переносится порядка 1/N данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 3, 'Что происходит с запросом, который не содержит ключа шардирования?', '["Идёт на случайный шард","Отправляется на все шарды, и ответы склеиваются","Отклоняется","Идёт на лидер"]', 1, 'Это обход со сбором (scatter-gather): медленнее, нагружает все шарды, задержка равна самому медленному.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 5, 4, 'Что следует сделать до шардирования?', '["Ничего — сразу шардировать","Индексы, кэш, реплики, архивирование и секционирование","Купить сервер вдвое мощнее и забыть","Отключить транзакции"]', 1, 'Шардирование — крайняя мера: оно усложняет запросы, транзакции и эксплуатацию.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 6, 'theory', 'Квиз: согласованность и идемпотентность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 0, 'Что выбирает система при разделении сети с точки зрения теоремы CAP?', '["Между быстродействием и стоимостью","Между согласованностью и доступностью","Между двумя регионами","Между чтением и записью"]', 1, 'Разделение неизбежно; на время сбоя система либо отказывается отвечать (C), либо отвечает возможно устаревшим (A).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 1, 'Почему «ровно один раз» на практике реализуют как «не менее одного раза» плюс идемпотентность?', '["Так дешевле хранить","Чистая доставка ровно один раз в распределённой системе недостижима","Так принято в протоколах","Это быстрее"]', 1, 'Сообщения могут дублироваться; идемпотентный получатель делает эффект равным однократному.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 2, 'Какая операция идемпотентна?', '["balance = balance + 100","установить статус заказа «оплачен»","добавить запись в журнал","отправить письмо"]', 1, 'Установка значения при повторе даёт тот же результат; прибавление накапливается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 3, 'Чем опасны повторы без паузы при перегрузке сервиса?', '["Ничем","Усиливают перегрузку: нагрузка кратно растёт, сервис не может восстановиться","Ускоряют ответ","Снижают задержку"]', 1, 'Retry storm: клиенты умножают нагрузку; нужны нарастающая пауза, джиттер, бюджет повторов и автомат разрыва.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 6, 4, 'Для чего служит сага?', '["Для шифрования","Для длинной операции через несколько сервисов: шаги с компенсирующими действиями вместо блокировок","Для кэширования","Для балансировки"]', 1, 'Сага — цепочка локальных транзакций; при сбое выполняют компенсации в обратном порядке.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 7, 'theory', 'Квиз: поиск и файлы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 0, 'Почему запрос с подстрокой по тексту плохо подходит для поиска на большой таблице?', '["Он не поддерживается базами","Он перебирает все строки, не ранжирует и не учитывает язык","Он слишком дёшев","Он требует шардов"]', 1, 'Подстрока без индекса даёт полный перебор; для поиска строят обратный индекс.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 1, 'Что хранит обратный индекс?', '["Для каждого документа его автора","Для каждого слова список документов, где оно встречается","Копию всей базы","Только популярные запросы"]', 1, 'Запрос по словам превращается в пересечение списков документов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 2, 'Что определяет число реплик поискового кластера, а что — число шардов?', '["Реплики — объём, шарды — нагрузка","Шарды — объём индекса, реплики — пропускная способность и отказоустойчивость","И то и другое — стоимость","Шарды — язык, реплики — регион"]', 1, 'Шардов столько, чтобы шард не рос выше десятков гигабайт; реплики добавляют для запросов и надёжности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 3, 'Как правильно загружать большие файлы?', '["Через сервер приложения целиком","Напрямую в объектное хранилище по временной подписанной ссылке, частями","Через базу данных","По электронной почте"]', 1, 'Так приложение не тратит соединения и память на передачу байтов; докачка — по частям.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 7, 4, 'Почему поисковый индекс не считают источником истины?', '["Он слишком маленький","Это производная копия: при потере его пересобирают из основной базы","Он не хранит текст","Он хранится в браузере"]', 1, 'Источник правды — основная база; индекс обновляется асинхронно и может отставать.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 8, 'theory', 'Квиз: очереди и обработчики');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 0, 'Что произойдёт, если потребитель выполнил работу и упал до подтверждения?', '["Сообщение пропадёт","Сообщение вернётся в очередь и будет обработано снова","Брокер остановится","Сообщение удалится из базы"]', 1, 'Без подтверждения брокер возвращает сообщение: доставка «не менее одного раза», поэтому нужна идемпотентность.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 1, 'Что ограничивает число параллельных потребителей в группе при партиционированной очереди?', '["Размер сообщения","Число партиций","Число производителей","Объём диска"]', 1, 'Одну партицию читает один потребитель группы; лишние потребители простаивают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 2, 'Для чего нужна очередь недоставленных сообщений (DLQ)?', '["Для хранения резервных копий","Чтобы ядовитые сообщения не блокировали остальные и их можно было разобрать вручную","Для ускорения доставки","Для шифрования"]', 1, 'После ограниченного числа попыток сообщение уходит в DLQ; рост её длины — повод для оповещения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 3, 'Какая метрика лучше всего показывает, что обработчиков не хватает?', '["Загрузка процессора производителя","Отставание очереди (lag)","Размер сообщения","Число партиций"]', 1, 'Растущее отставание означает, что сообщения поступают быстрее, чем обрабатываются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 4, 'Как атомарно связать запись в базу и отправку сообщения?', '["Сначала отправить, потом записать","Паттерн исходящих сообщений: сообщение пишется в таблицу той же транзакцией, а публикует его отдельный процесс","Отправлять дважды","Использовать один процесс"]', 1, 'Outbox исключает потерю: запись и намерение сохраняются в одной транзакции.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 9, 'theory', 'Квиз: устойчивость');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 0, 'Почему повторы на каждом уровне цепочки вызовов опасны?', '["Они ускоряют ответ","Нагрузка на нижний сервис умножается: 3 уровня по 3 попытки — 27 запросов","Они не работают с таймаутами","Они уменьшают число серверов"]', 1, 'Повторы перемножаются; повторять должен только один уровень, остальные отказывают быстро.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 1, 'Что делает автомат разрыва в разомкнутом состоянии?', '["Пропускает все запросы","Сразу отказывает, не обращаясь к зависимости, и периодически пробует восстановиться","Увеличивает таймаут","Отключает мониторинг"]', 1, 'Быстрый отказ защищает и вызывающего, и больную зависимость; через паузу — пробные запросы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 2, 'В чём преимущество алгоритма «ведро токенов»?', '["Он не требует памяти","Он допускает короткие всплески при ограниченной средней скорости","Он блокирует все запросы","Он работает только с шардами"]', 1, 'Токены накапливаются до размера ведра: всплеск возможен, а средняя скорость ограничена скоростью пополнения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 3, 'Что такое сброс нагрузки (load shedding)?', '["Перезапуск серверов","Быстрый отказ на часть запросов, начиная с наименее важных, чтобы остальные обслужить хорошо","Удаление данных","Отключение мониторинга"]', 1, 'При перегрузке лучше хорошо обслужить часть запросов, чем плохо все.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 9, 4, 'Зачем нужны переборки (bulkhead)?', '["Для шифрования","Чтобы сбой или перегрузка одной зависимости не исчерпала общие ресурсы и не затронула остальные","Для кэширования","Для балансировки между регионами"]', 1, 'Отдельные пулы соединений и квоты делают сбой локальным.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 10, 'theory', 'Квиз: микросервисы и шлюз');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 0, 'Когда монолит предпочтительнее микросервисов?', '["Никогда","Когда команда и продукт небольшие: проще разрабатывать, отлаживать и выкладывать","Только для баз данных","Когда много серверов"]', 1, 'Микросервисы меняют простоту на независимость; для небольших продуктов налог распределённости не оправдан.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 1, 'Почему у каждого микросервиса должна быть своя база?', '["Так дешевле","Общая база скрыто связывает сервисы: изменение таблицы ломает всех","Базы не умеют работать вместе","Это требует протокол"]', 1, 'Общие таблицы — самая сильная связь; владелец данных должен быть один.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 2, 'Какую роль выполняет API-шлюз?', '["Хранит данные","Единая входная точка: маршрутизация, аутентификация, лимиты, агрегация","Заменяет базу","Шифрует диски"]', 1, 'Шлюз скрывает набор сервисов от клиента и берёт на себя общие функции входа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 3, 'Что считается совместимым изменением интерфейса?', '["Удалить поле","Добавить необязательное поле","Изменить тип поля","Переименовать метод"]', 1, 'Добавление необязательного не ломает старых клиентов; удаление и смена смысла ломают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 10, 4, 'Чем заменяют транзакции, затрагивающие несколько микросервисов?', '["Одной общей транзакцией","Сагами и событиями с согласованностью в конечном счёте","Блокировкой всех баз","Ничем — такие операции запрещены"]', 1, 'Цепочка локальных шагов с компенсациями; данные синхронизируются событиями.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 11, 'theory', 'Квиз: реальное время');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 0, 'Чем WebSocket отличается от обычного HTTP-запроса?', '["Он работает без сети","После рукопожатия соединение остаётся открытым, и обе стороны могут отправлять данные в любой момент","Он не требует сервера","Он всегда быстрее"]', 1, 'Это долгоживущее двустороннее соединение; ресурсом становится число открытых соединений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 1, 'Какой ресурс главный при масштабировании шлюзов WebSocket?', '["Скорость диска","Число одновременно открытых соединений: дескрипторы и память","Размер базы","Пропускная способность DNS"]', 1, 'Один шлюз держит десятки тысяч соединений; шлюзы масштабируют по их числу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 2, 'Как избежать шторма подключений после падения шлюза?', '["Ничего не делать","Клиенты переподключаются с нарастающей паузой и случайным разбросом, шлюзы ограничивают скорость приёма","Отключить всех клиентов","Запретить переподключения"]', 1, 'Иначе все клиенты одновременно бросятся на оставшиеся шлюзы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 3, 'Как хранят статус «онлайн»?', '["В основной базе с записью при каждом изменении","В быстром кэше с коротким TTL, обновляемым сердцебиением","В журнале сервера","В браузере"]', 1, 'Запись истекает, когда сердцебиение прекратилось; точность в секунды не нужна.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 11, 4, 'Как клиент восстанавливает историю после переподключения?', '["Заново загружает всё","Сообщает номер последнего полученного сообщения, и сервер досылает пропущенные","Ждёт нового сообщения","Не восстанавливает"]', 1, 'Номер в чате задаёт порядок; докачка по последнему номеру не теряет сообщений.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 12, 'theory', 'Квиз: лента новостей');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 0, 'В чём главный недостаток схемы pull (сборка ленты при чтении)?', '["Дорогая запись","Тяжёлое чтение: десятки запросов на каждое открытие ленты","Нужны реплики","Нельзя кэшировать"]', 1, 'Нагрузка на чтение растёт с числом подписок; запись же дёшева.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 1, 'Почему push плохо работает для знаменитостей?', '["Они пишут слишком редко","Один пост порождает миллионы записей в ленты подписчиков","Знаменитости не используют ленты","Push не использует кэш"]', 1, 'Рассылка на миллионы подписчиков даёт всплеск нагрузки и задержку публикации.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 2, 'Что делает гибридный подход?', '["Использует только pull","Рассылает посты обычных авторов, а посты знаменитостей подмешивает при чтении","Использует только push","Не хранит посты"]', 1, 'Так записи недороги, а чтение добавляет лишь немного свежих постов знаменитостей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 3, 'Что хранят в готовой ленте пользователя?', '["Тексты постов целиком","Идентификаторы постов","Картинки","Пароли"]', 1, 'Так экономится память и правка поста не требует обновления тысяч лент; пагинация — по курсору.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 4, 'Как поступают с лентами неактивных пользователей?', '["Обновляют каждую секунду","Не поддерживают: запись истекает, ленту собирают при возвращении","Удаляют аккаунты","Шифруют"]', 1, 'Это резко снижает объём работы при рассылке; медленнее только при редком возвращении.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 13, 'theory', 'Квиз: типовые задачи');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 0, 'Сколько комбинаций даёт ключ из 7 символов base62?', '["Около 62 тысяч","Около 3,5 триллиона","Около 7 миллионов","Около 100 миллиардов"]', 1, '62⁷ ≈ 3,5·10¹² — хватает на десятилетия при сотнях миллионов ссылок в месяц.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 1, 'В чём разница редиректов 301 и 302 для сокращателя?', '["301 временный, 302 постоянный","301 браузер запоминает — меньше нагрузки, но нет статистики кликов; 302 проходит через сервис каждый раз","Разницы нет","301 шифрует адрес"]', 1, 'Выбор определяется требованием к аналитике кликов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 2, 'Как справляются с «горячей строкой» счётчика просмотров?', '["Увеличивают размер диска","Буферизуют приращения и записывают пачками, шардируют счётчик на части","Запрещают просмотры","Отключают индексы"]', 1, 'Накапливаем в памяти и сбрасываем раз в несколько секунд; чтение — сумма частей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 3, 'Из чего состоит идентификатор в схеме Snowflake?', '["Только из случайных байтов","Из времени, номера узла и счётчика внутри миллисекунды","Из хеша адреса","Из имени пользователя"]', 1, 'Он помещается в 8 байт, примерно упорядочен по времени и генерируется независимо на каждом узле.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 4, 'Почему операции проверки и обновления в общем ограничителе должны быть атомарными?', '["Так быстрее читать журнал","Иначе параллельные запросы обгонят друг друга и пропустят больше нормы","Для шифрования","Для сжатия"]', 1, 'Без атомарности два одновременных запроса прочитают один и тот же остаток токенов.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 14, 'theory', 'Квиз: наблюдаемость и SLO');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 0, 'Что показывают три столпа наблюдаемости?', '["Метрики — что происходит, трассы — где теряется время, журналы — что и почему случилось","Только метрики","Только журналы","Только трассы"]', 0, 'Три вида данных дополняют друг друга и связываются общими идентификаторами запроса.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 1, 'Какие четыре «золотых сигнала» стоит измерять?', '["Задержка, трафик, ошибки, насыщение","Загрузка CPU, RAM, диск, сеть","Цена, время, место, люди","Логи, метрики, трассы, алерты"]', 0, 'Задержка (в перцентилях), трафик, доля ошибок и насыщение ограниченных ресурсов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 2, 'Сколько допустимо простоя в месяц при SLO 99,9% (≈ 30 дней)?', '["Около 4 часов","Около 43 минут","Около 5 минут","Около 7 часов"]', 1, '0,1% от 30 суток — примерно 43 минуты: это бюджет ошибок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 3, 'На что лучше привязывать срочные оповещения?', '["На загрузку процессора выше 90%","На симптомы для пользователя и скорость сгорания бюджета ошибок","На любое предупреждение в журнале","На размер диска"]', 1, 'Так будят только по делу; ложные тревоги вызывают усталость дежурных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 14, 4, 'Какова главная цель разбора инцидента (постмортема)?', '["Найти и наказать виновного","Понять причины на системном уровне и снизить вероятность повторения","Написать отчёт для руководства","Удалить журналы"]', 1, 'Культура без обвинений сохраняет честные рассказы об ошибках — единственный источник улучшений.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 15, 'theory', 'Квиз: зоны и регионы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 0, 'Что такое домен отказа?', '["Тип базы","Группа ресурсов, ломающихся одновременно: хост, стойка, зона, регион","Название сервиса","Протокол репликации"]', 1, 'Копии размещают в разных доменах отказа, чтобы потеря одного не лишила схему всех копий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 1, 'Почему между зонами одного региона возможна синхронная репликация, а между регионами — обычно нет?', '["Между зонами нет сети","Задержка между зонами ~1 мс, между регионами — десятки и сотни мс","Регионы не поддерживают репликацию","Зоны дороже"]', 1, 'Синхронная запись ждёт подтверждения: сотни мс на каждую операцию недопустимы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 2, 'В чём риск гео-DNS при переключении региона?', '["Он шифрует трафик","Клиенты кэшируют старый адрес ещё несколько минут, поэтому TTL делают коротким","DNS не работает с регионами","Он увеличивает задержку навсегда"]', 1, 'Кэширование записей замедляет переключение; помогают короткий TTL и глобальный балансировщик.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 3, 'Какую опасность часто упускают в двухрегиональной схеме?', '["Слишком много серверов","Общие зависимости (DNS, сертификаты, конфигурация), расположенные в одном регионе","Слишком дорогие реплики","Лишние метрики"]', 1, 'Общая служба в одном регионе роняет оба; нужно проверить каждую зависимость.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 15, 4, 'Что даёт ячеистая архитектура (cell-based)?', '["Дешевле хранение","Ограничивает радиус поражения: сбой или плохая выкладка затрагивает лишь долю пользователей","Ускоряет сеть","Убирает базы данных"]', 1, 'Каждая ячейка — независимый экземпляр сервиса для части пользователей.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 16, 'theory', 'Квиз: CI/CD и выкладка');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 0, 'Почему артефакт (образ) собирают один раз и разворачивают во все среды?', '["Так дешевле","В рабочую среду должно попасть ровно то, что тестировали","Так требует реестр","Это ускоряет сеть"]', 1, 'Пересборка для каждой среды рискует выкатить не то, что прошло проверки; различия задаёт конфигурация.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 1, 'Каков главный риск rolling-выкладки двух серверов?', '["Нужна копия среды","На время выкладки теряется половина мощности, а две версии кода работают одновременно","Нельзя откатить","Не нужен балансировщик"]', 1, 'Запас должен покрывать потерю одного сервера; изменения должны быть обратно совместимы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 2, 'В чём цена схемы blue/green?', '["Простой сервиса","Двойные ресурсы на время выкладки и совместимость схемы базы с обеими версиями","Невозможность отката","Отсутствие мониторинга"]', 1, 'Зато переключение и откат мгновенные, а мощность не падает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 3, 'Что делает canary-выкладка?', '["Останавливает сервис","Направляет малую долю трафика на новую версию, сравнивает метрики и откатывает при ухудшении","Копирует базу","Отключает мониторинг"]', 1, 'Пострадает лишь небольшой процент пользователей, а доля растёт ступенями.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 16, 4, 'Как безопасно удалить поле из базы без простоя?', '["Удалить сразу при выкладке","Расширить → перейти на новое → когда все версии перешли, удалить старое","Остановить сервис и удалить","Переименовать поле"]', 1, 'Схема общая для старой и новой версий кода: удаление — последний шаг после перехода всех.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 17, 'theory', 'Квиз: облако и стоимость');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 0, 'Какой тариф подходит для постоянной базовой нагрузки?', '["Спот","Резервирование на 1–3 года со скидкой около 40%","Только по требованию","Бесплатный"]', 1, 'Постоянная нагрузка предсказуема, и скидка за обязательство окупается; пики — по требованию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 1, 'Для чего хорошо подходят спот-экземпляры?', '["Для единственной базы данных","Для пакетных задач и обработчиков, терпящих прерывание","Для DNS","Для хранения паролей"]', 1, 'Спот дешевле в 3–4 раза, но может быть отобран за минуту.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 2, 'Что обычно платно в облаке?', '["Входящий трафик","Исходящий и межрегиональный трафик","Время простоя ноутбука","Создание тегов"]', 1, 'Исходящий трафик дорог; CDN, сжатие и размещение рядом снижают счёт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 3, 'Что даёт инфраструктура как код?', '["Нет серверов","Воспроизводимость, ревью изменений и возможность восстановить среду","Увеличение нагрузки","Отключение мониторинга"]', 1, 'Декларативное описание в репозитории: изменения проходят ревью и конвейер; дрейф обнаруживают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 4, 'Когда функции как услуга невыгодны?', '["При редких и неравномерных задачах","При ровном постоянном высоком потоке: обычные серверы дешевле","При обработке событий загрузки","При веб-хуках"]', 1, 'Оплата за вызовы выгодна на пиках и нулевой нагрузке, но постоянный поток дешевле на постоянных серверах.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 18, 'theory', 'Квиз: итоговый проект');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 0, 'С чего начинается проектирование сервиса?', '["С выбора технологий","С требований и чисел: функции, нагрузка, объём, SLO, бюджет","С покупки серверов","С написания кода"]', 1, 'Числа определяют, какие кирпичи нужны; без них схема строится вслепую.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 1, 'Почему видео в проекте раздают через CDN и объектное хранилище, а не через серверы приложения?', '["Так принято","Иначе не хватит никакого парка серверов и счёта за трафик; хранилище и CDN дешевле и рассчитаны на это","Серверы не умеют читать файлы","CDN шифрует видео"]', 1, 'Серверы приложения отвечают за метаданные и подписанные ссылки, а байты раздаёт CDN.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 2, 'Почему перекодирование видео делают асинхронно через очередь?', '["Чтобы замедлить загрузку","Задача тяжёлая и долгая: очередь сглаживает пики и позволяет масштабировать обработчиков и запускать их на споте","Так проще писать код","Чтобы сэкономить на CDN"]', 1, 'Пользователь сразу получает подтверждение; обработчики идемпотентны и масштабируются по отставанию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 3, 'Как строится лента в итоговом проекте?', '["Только pull","Только push","Гибрид: рассылка для обычных авторов и подмешивание знаменитостей при чтении","Случайным образом"]', 2, 'Гибрид решает проблему знаменитостей и держит записи недорогими.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 4, 'Что оценивается в ответе на задачу по системному дизайну?', '["Количество названных технологий","Цепочка рассуждений: требования, числа, узкие места, отказы и компромиссы","Скорость рисования","Единственно верная схема"]', 1, 'Важно показать, как вы рассуждаете и меняете решение при изменении требований.');
